// Generate metadata
const eventId = 'gdacs-' + Date.now() + '-' + Math.random().toString(36).substr(2, 9);
return [{
  eventId: eventId,
  workflowName: 'Harvy — gdacs Ingestion',
  timestamp: new Date().toISOString(),
  source: 'gdacs'
}];

// Configuration setup
const config = {
  gdacsApi: 'https://www.gdacs.org/api/v2/alerts',
  proxy: {
    host: process.env.WEBSHARE_PROXY_URL ? process.env.WEBSHARE_PROXY_URL.split('://')[1].split(':')[0] : '',
    port: process.env.WEBSHARE_PROXY_URL ? parseInt(process.env.WEBSHARE_PROXY_URL.split(':')[2]) : 0
  }
};
return [config];

// Process alerts with provenance
const alerts = items.map(item => {
  const alert = item.json;
  const eventId = 'gdacs-alert-' + alert.id + '-' + alert.timestamp;

  return {
    ...alert,
    eventId: eventId,
    workflowName: 'Harvy — gdacs Ingestion',
    ingestionTimestamp: new Date().toISOString(),
    provenance: {
      source: 'gdacs.org',
      retrievedAt: new Date().toISOString(),
      license: 'CC-BY-4.0'
    },
    dedupeKey: alert.id + '-' + alert.timestamp
  };
});
return alerts;

// Simple deduplication
const seen = new Set();
const unique = [];
const duplicates = [];

for (const item of items) {
  if (!seen.has(item.json.dedupeKey)) {
    seen.add(item.json.dedupeKey);
    unique.push(item);
  } else {
    duplicates.push(item);
  }
}

if (duplicates.length > 0) {
  console.warn('Duplicate alerts found:', duplicates.length);
}

return { uniqueAlerts: unique, duplicateCount: duplicates.length };

// Prepare for storage
const alerts = items.map(item => item.json);

const rawData = alerts.map(a => ({
  eventId: a.eventId,
  source: 'gdacs',
  rawJson: JSON.stringify(a),
  timestamp: a.timestamp,
  ingestionTimestamp: a.ingestionTimestamp
}));

const processedData = alerts.map(a => ({
  eventId: a.eventId,
  alertId: a.id,
  title: a.title || '',
  severity: a.severity || 'unknown',
  timestamp: a.timestamp,
  location: JSON.stringify(a.location || {}),
  workflowName: a.workflowName
}));

return [{ rawData, processedData }];
